-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — Itálie II: Apeniny, jih a ostrovy (IT)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Apeniny – Passo della Futa a Raticosa
  delete from public.routes where name = 'Apeniny – Passo della Futa a Raticosa' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Apeniny – Passo della Futa a Raticosa', 'Nedělní svatyně italských motorkářů: legendární průsmyky Futa a Raticosa na staré silnici SS65 mezi Florencií a Bolognou. Čeká tě nekonečný sled plynulých zatáček s výborným asfaltem, výhledy na zelené hřebeny Apenin a zastávka u okruhu Mugello, kde jezdí MotoGP. Okruh doplňuje klikatý průsmyk Giogo a kamenné městečko Firenzuola. Nejlépe od dubna do října; o víkendech počítej s hustým provozem motorek a občasným měřením rychlosti. Na Raticose nevynechej kultovní motorkářský Chalet.', 'loop', 115, 210, 'medium',
     '[{"lat": 43.9954, "lng": 11.3541, "label": "Start: Scarperia"}, {"lat": 43.9975, "lng": 11.3719, "label": "Autodromo del Mugello"}, {"lat": 44.0480, "lng": 11.3540, "label": "Passo del Giogo"}, {"lat": 44.1190, "lng": 11.3810, "label": "Firenzuola"}, {"lat": 44.1611, "lng": 11.3536, "label": "Passo della Raticosa"}, {"lat": 44.0940, "lng": 11.2860, "label": "Passo della Futa"}, {"lat": 43.9800, "lng": 11.2670, "label": "Lago di Bilancino"}, {"lat": 43.9954, "lng": 11.3541, "label": "Cíl: Scarperia"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.9954,11.3541&destination=43.9954,11.3541&travelmode=driving&waypoints=43.9975,11.3719%7C44.0480,11.3540%7C44.1190,11.3810%7C44.1611,11.3536%7C44.0940,11.2860%7C43.9800,11.2670', 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Futa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palazzo%20dei%20Vicari%2C%20Scarperia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Autodromo%20del%20Mugello.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Raticosa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Futa.jpg"}'::text[], '{"Scarperia – Palazzo dei Vicari","Autodromo del Mugello","Passo della Raticosa","Passo della Futa"}'::text[], '{"IT"}'::text[], false, 4410, 'approved');

  -- Umbrie – Assisi, Spoleto a vodopády Marmore
  delete from public.routes where name = 'Umbrie – Assisi, Spoleto a vodopády Marmore' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Umbrie – Assisi, Spoleto a vodopády Marmore', 'Zelené srdce Itálie bez davů Toskánska: poutní Assisi s bazilikou sv. Františka, růžové Spello, vinařské Montefalco a Spoleto s monumentálním akvaduktem. Velkolepé finále obstarají vodopády Marmore — nejvyšší umělé vodopády Evropy, které Římané postavili už před dvěma tisíci lety. Silnice se vlní mezi olivovými háji a vinicemi, provoz je mírný a asfalt slušný. Ideální od jara do podzimu; u Marmore si ohlídej časy pouštění vody. V létě počítej v Assisi s poutníky a placeným parkováním.', 'loop', 205, 300, 'easy',
     '[{"lat": 43.1107, "lng": 12.3908, "label": "Start: Perugia"}, {"lat": 43.0748, "lng": 12.6054, "label": "Assisi"}, {"lat": 42.9910, "lng": 12.6710, "label": "Spello"}, {"lat": 42.8930, "lng": 12.6540, "label": "Montefalco"}, {"lat": 42.7400, "lng": 12.7370, "label": "Spoleto"}, {"lat": 42.5510, "lng": 12.7150, "label": "Cascata delle Marmore"}, {"lat": 43.1107, "lng": 12.3908, "label": "Cíl: Perugia"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.1107,12.3908&destination=43.1107,12.3908&travelmode=driving&waypoints=43.0748,12.6054%7C42.9910,12.6710%7C42.8930,12.6540%7C42.7400,12.7370%7C42.5510,12.7150', 'https://commons.wikimedia.org/wiki/Special:FilePath/Assisi%20San%20Francesco%20BW%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20Maggiore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Assisi%20San%20Francesco%20BW%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Spoleto%20Ponte%20delle%20Torri.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cascata%20delle%20Marmore.jpg"}'::text[], '{"Perugia – Fontana Maggiore","Assisi – bazilika sv. Františka","Spoleto – Ponte delle Torri","Cascata delle Marmore"}'::text[], '{"IT"}'::text[], false, 4420, 'approved');

  -- Marche – Riviera del Conero a Loreto
  delete from public.routes where name = 'Marche – Riviera del Conero a Loreto' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Marche – Riviera del Conero a Loreto', 'Bílé vápencové útesy hory Conero padající do tyrkysového Jadranu — nejkrásnější kus pobřeží mezi Terstem a Gargánem. Pobřežní silnice provoněná borovicemi spojuje zátoku Portonovo s výletními městečky Sirolo a Numana, pak se stočíš do vnitrozemí k poutnímu Loretu a básníkovu Recanati. Krátká, pohodová trasa s lehkými zatáčkami a spoustou vyhlídek, ideální i na půlden. Nejhezčí je mimo červencové a srpnové špičky, kdy pobřeží houstne. Pozor na cyklisty a víkendový provoz u pláží.', 'loop', 110, 180, 'easy',
     '[{"lat": 43.6169, "lng": 13.5189, "label": "Start: Ancona"}, {"lat": 43.5640, "lng": 13.5900, "label": "Portonovo"}, {"lat": 43.5230, "lng": 13.6210, "label": "Sirolo"}, {"lat": 43.5130, "lng": 13.6220, "label": "Numana"}, {"lat": 43.4400, "lng": 13.6100, "label": "Loreto"}, {"lat": 43.4030, "lng": 13.5490, "label": "Recanati"}, {"lat": 43.6169, "lng": 13.5189, "label": "Cíl: Ancona"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.6169,13.5189&destination=43.6169,13.5189&travelmode=driving&waypoints=43.5640,13.5900%7C43.5230,13.6210%7C43.5130,13.6220%7C43.4400,13.6100%7C43.4030,13.5490', 'https://commons.wikimedia.org/wiki/Special:FilePath/Spiaggia%20delle%20Due%20Sorelle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Ancona.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Portonovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spiaggia%20delle%20Due%20Sorelle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Loreto.jpg"}'::text[], '{"Ancona – katedrála San Ciriaco","Portonovo","Sirolo a pláž Due Sorelle","Loreto – Basilica della Santa Casa"}'::text[], '{"IT"}'::text[], false, 4430, 'approved');

  -- Abruzzo – Gran Sasso a Campo Imperatore
  delete from public.routes where name = 'Abruzzo – Gran Sasso a Campo Imperatore' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Abruzzo – Gran Sasso a Campo Imperatore', 'Malé italské Tibety: náhorní planina Campo Imperatore v 1800 metrech, kde se pod nejvyšší horou Apenin Corno Grande (2912 m) pasou polodivocí koně a natáčely se westerny. Silnice bez svodidel se vlní otevřenou krajinou, jakou jinde v Itálii nenajdeš. Cestou zpět středověké perly — hradní zřícenina Rocca Calascio z filmu Ladyhawke a kamenná vesnice Santo Stefano di Sessanio. Jezdi od června do září, planina je vysoko a počasí se mění rychle; brzy na jaře a na podzim hrozí sníh. Vezmi teplou vrstvu i v létě.', 'loop', 150, 240, 'medium',
     '[{"lat": 42.3499, "lng": 13.3995, "label": "Start: L''Aquila"}, {"lat": 42.4422, "lng": 13.5589, "label": "Campo Imperatore"}, {"lat": 42.3650, "lng": 13.7260, "label": "Castel del Monte"}, {"lat": 42.3280, "lng": 13.6880, "label": "Rocca Calascio"}, {"lat": 42.3430, "lng": 13.6460, "label": "Santo Stefano di Sessanio"}, {"lat": 42.3499, "lng": 13.3995, "label": "Cíl: L''Aquila"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.3499,13.3995&destination=42.3499,13.3995&travelmode=driving&waypoints=42.4422,13.5589%7C42.3650,13.7260%7C42.3280,13.6880%7C42.3430,13.6460', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rocca%20Calascio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Santa%20Maria%20di%20Collemaggio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Campo%20Imperatore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rocca%20Calascio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Santo%20Stefano%20di%20Sessanio.jpg"}'::text[], '{"L''Aquila – bazilika Collemaggio","Campo Imperatore","Rocca Calascio","Santo Stefano di Sessanio"}'::text[], '{"IT"}'::text[], false, 4440, 'approved');

  -- Piemont – vinice Langhe a Barolo
  delete from public.routes where name = 'Piemont – vinice Langhe a Barolo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Piemont – vinice Langhe a Barolo', 'Vlnící se kopce Langhe (UNESCO) — nekonečné vinice nebbiola, hrady na hřebenech a vesnice, jejichž jména zná každý milovník vína: Barolo, La Morra, Barbaresco. Silničky třetí třídy se kroutí po hřebenech vinic s výhledy na zasněžené Alpy na obzoru. Krátká vzdálenost, ale počítej s celým dnem — každá zastávka svádí k ochutnávce a lanýžové kuchyni (řidič samozřejmě střídmě). Nejkrásnější je podzim, kdy vinice zezlátnou a v Albě voní lanýže. Pozor na úzké silnice mezi vinicemi a traktory ve špičce vinobraní.', 'loop', 95, 180, 'easy',
     '[{"lat": 44.7009, "lng": 8.0353, "label": "Start: Alba"}, {"lat": 44.6560, "lng": 8.0090, "label": "Grinzane Cavour"}, {"lat": 44.6370, "lng": 7.9330, "label": "La Morra"}, {"lat": 44.6110, "lng": 7.9430, "label": "Barolo"}, {"lat": 44.6100, "lng": 8.0000, "label": "Serralunga d''Alba"}, {"lat": 44.7260, "lng": 8.0810, "label": "Barbaresco"}, {"lat": 44.7009, "lng": 8.0353, "label": "Cíl: Alba"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.7009,8.0353&destination=44.7009,8.0353&travelmode=driving&waypoints=44.6560,8.0090%7C44.6370,7.9330%7C44.6110,7.9430%7C44.6100,8.0000%7C44.7260,8.0810', 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Grinzane%20Cavour.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Alba.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Grinzane%20Cavour.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/La%20Morra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Barolo.jpg"}'::text[], '{"Alba","Castello di Grinzane Cavour","La Morra – vyhlídka Belvedere","Barolo – Castello Falletti"}'::text[], '{"IT"}'::text[], false, 4450, 'approved');

  -- Údolí Aosty – hrady pod Mont Blankem
  delete from public.routes where name = 'Údolí Aosty – hrady pod Mont Blankem' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Aosty – hrady pod Mont Blankem', 'Projížďka nejmenším italským regionem od pevnosti Bard až pod stěnu Mont Blanku. Údolím Dora Baltea se řadí hrad za hradem — Bard, Fénis, Saint-Pierre — mezi nimi římská Aosta s triumfálním obloukem a divadlem. Finále patří Courmayeur a lanovce Skyway, která tě otočnou kabinou vyveze do 3466 metrů na Punta Helbronner. Jeď po staré silnici SS26, dálnici nech kamionům; stoupání je pozvolné a zvládne ho každý. Ideální červen až září; nad 2000 metrů bývá chladno i v létě.', 'poi', 100, 150, 'easy',
     '[{"lat": 45.5980, "lng": 7.7960, "label": "Start: Pont-Saint-Martin"}, {"lat": 45.6080, "lng": 7.7440, "label": "Forte di Bard"}, {"lat": 45.7360, "lng": 7.4900, "label": "Castello di Fénis"}, {"lat": 45.7390, "lng": 7.3260, "label": "Aosta"}, {"lat": 45.7100, "lng": 7.2230, "label": "Castello di Saint-Pierre"}, {"lat": 45.7920, "lng": 6.9720, "label": "Courmayeur"}, {"lat": 45.8140, "lng": 6.9660, "label": "Cíl: Skyway Monte Bianco"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.5980,7.7960&destination=45.8140,6.9660&travelmode=driving&waypoints=45.6080,7.7440%7C45.7360,7.4900%7C45.7390,7.3260%7C45.7100,7.2230%7C45.7920,6.9720', 'https://commons.wikimedia.org/wiki/Special:FilePath/Forte%20di%20Bard.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Forte%20di%20Bard.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20F%C3%A9nis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arco%20di%20Augusto%20Aosta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skyway%20Monte%20Bianco.jpg"}'::text[], '{"Forte di Bard","Castello di Fénis","Aosta – Arco di Augusto","Skyway Monte Bianco"}'::text[], '{"IT"}'::text[], false, 4460, 'approved');

  -- Ligurské vnitrozemí – Dolceacqua a Triora
  delete from public.routes where name = 'Ligurské vnitrozemí – Dolceacqua a Triora' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Ligurské vnitrozemí – Dolceacqua a Triora', 'Zapomenutá Ligurie pár kilometrů od riviéry: kamenné vesnice přilepené na skalách, jednopruhé silničky v roklích a středověké mosty, které maloval Monet. Z Ventimiglie stoupáš údolím Nervia přes Dolceacquu a orlí hnízdo Apricale, pak přes horské sedlo do údolí Argentina k "vesnici čarodějnic" Triora. Zpátky k moři podél řeky do Taggie a po pobřeží přes Sanremo. Úzké serpentiny vyžadují soustředění a čistou techniku — trasa pro zkušenější jezdce. Nejlépe na jaře a na podzim; v létě je u pobřeží rušno, ale vnitrozemí zůstává liduprázdné.', 'loop', 130, 270, 'hard',
     '[{"lat": 43.7900, "lng": 7.6070, "label": "Start: Ventimiglia"}, {"lat": 43.8480, "lng": 7.6220, "label": "Dolceacqua"}, {"lat": 43.8800, "lng": 7.6600, "label": "Apricale"}, {"lat": 43.9320, "lng": 7.6620, "label": "Pigna"}, {"lat": 44.0000, "lng": 7.7640, "label": "Triora"}, {"lat": 43.8620, "lng": 7.8510, "label": "Taggia"}, {"lat": 43.8160, "lng": 7.7760, "label": "Sanremo"}, {"lat": 43.7900, "lng": 7.6070, "label": "Cíl: Ventimiglia"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.7900,7.6070&destination=43.7900,7.6070&travelmode=driving&waypoints=43.8480,7.6220%7C43.8800,7.6600%7C43.9320,7.6620%7C44.0000,7.7640%7C43.8620,7.8510%7C43.8160,7.7760', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dolceacqua.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dolceacqua.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Apricale.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Triora.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sanremo.jpg"}'::text[], '{"Dolceacqua","Apricale","Triora","Sanremo"}'::text[], '{"IT"}'::text[], false, 4470, 'approved');

  -- Sicílie – barokní Val di Noto
  delete from public.routes where name = 'Sicílie – barokní Val di Noto' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sicílie – barokní Val di Noto', 'Jihovýchod Sicílie, kde po zemětřesení 1693 vyrostla nejkrásnější barokní města Evropy — dnes všechna na seznamu UNESCO. Ze Syrakus a ostrova Ortigia vede trasa medově zlatým Notem k rybářskému Marzamemi na samém jihu, pak vápencovými kaňony k filmovému Scicli, čokoládové Modice a velkolepé Ragusa Ibla. Silnice se vlní mezi kamennými zídkami, rohovníky a olivami; provoz je mimo města minimální. Ideální březen až červen a září až listopad — v létě tu bývá přes 35 °C. Ve městech parkuj ve stínu a hlídej si úzké jednosměrky.', 'loop', 225, 330, 'easy',
     '[{"lat": 37.0590, "lng": 15.2930, "label": "Start: Syrakusy (Ortigia)"}, {"lat": 36.8910, "lng": 15.0690, "label": "Noto"}, {"lat": 36.7370, "lng": 15.1180, "label": "Marzamemi"}, {"lat": 36.7900, "lng": 14.7060, "label": "Scicli"}, {"lat": 36.8590, "lng": 14.7610, "label": "Modica"}, {"lat": 36.9210, "lng": 14.7400, "label": "Ragusa Ibla"}, {"lat": 37.0590, "lng": 15.2930, "label": "Cíl: Syrakusy (Ortigia)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.0590,15.2930&destination=37.0590,15.2930&travelmode=driving&waypoints=36.8910,15.0690%7C36.7370,15.1180%7C36.7900,14.7060%7C36.8590,14.7610%7C36.9210,14.7400', 'https://commons.wikimedia.org/wiki/Special:FilePath/Noto%20Cathedral.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Siracusa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Noto%20Cathedral.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Marzamemi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ragusa%20Ibla.jpg"}'::text[], '{"Syrakusy – Ortigia","Noto – katedrála","Marzamemi","Ragusa Ibla"}'::text[], '{"IT"}'::text[], false, 4480, 'approved');

  -- Sardinie – Orientale Sarda a Supramonte
  delete from public.routes where name = 'Sardinie – Orientale Sarda a Supramonte' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sardinie – Orientale Sarda a Supramonte', 'Legendární silnice SS125 Orientale Sarda — divoký východ Sardinie mezi červenými skalami Arbataxu a vápencovými masivy Supramonte. Stará trasa přes sedlo Genna Silana (1017 m) je považována za nejkrásnější motorkářskou silnici ostrova: kilometry zatáček nad kaňonem Gorropu, nejhlubší soutěskou Evropy. Sjezd do Cala Gonone odmění tyrkysovým mořem a na závěr čekají slavné murály pastevecké vesnice Orgosolo. Jeď po staré SS125, ne po nové rychlostní silnici. Ideální květen, červen a září; v létě horko a plné pláže. Pozor na volně se pasoucí kozy a prasata na silnici.', 'poi', 160, 270, 'medium',
     '[{"lat": 39.9410, "lng": 9.7070, "label": "Start: Arbatax"}, {"lat": 40.0310, "lng": 9.6660, "label": "Baunei"}, {"lat": 40.1450, "lng": 9.4890, "label": "Genna Silana (Gorropu)"}, {"lat": 40.2910, "lng": 9.5900, "label": "Dorgali"}, {"lat": 40.2820, "lng": 9.6350, "label": "Cala Gonone"}, {"lat": 40.2050, "lng": 9.3540, "label": "Orgosolo"}, {"lat": 40.3210, "lng": 9.3300, "label": "Cíl: Nuoro"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=39.9410,9.7070&destination=40.3210,9.3300&travelmode=driving&waypoints=40.0310,9.6660%7C40.1450,9.4890%7C40.2910,9.5900%7C40.2820,9.6350%7C40.2050,9.3540', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gola%20di%20Gorropu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arbatax.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gola%20di%20Gorropu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cala%20Gonone.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orgosolo.jpg"}'::text[], '{"Arbatax – Rocce Rosse","Gola di Gorropu","Cala Gonone","Orgosolo – murály"}'::text[], '{"IT"}'::text[], false, 4490, 'approved');

  -- Gargano – Vieste a Foresta Umbra
  delete from public.routes where name = 'Gargano – Vieste a Foresta Umbra' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gargano – Vieste a Foresta Umbra', 'Ostruha italské boty: vápencový poloostrov Gargano, kde se pobřežní silnice SS89 mezi Vieste a Mattinatou počítá k nejkrásnějším přímořským cestám Itálie. Bílé útesy, skalní oblouky, zátoky s věžemi trabucchi a uprostřed poloostrova pralesovitá Foresta Umbra — buková rezervace UNESCO s chladivými serpentinami. K tomu poutní Monte Sant''Angelo s jeskynní svatyní archanděla Michaela. Zatáček je nepočítaně a tempo pomalé — na 185 km si nech celý den. Ideální květen, červen a září; v srpnu je pobřeží přeplněné. Pozor na písek v zatáčkách u pláží.', 'loop', 185, 300, 'medium',
     '[{"lat": 41.6260, "lng": 15.9110, "label": "Start: Manfredonia"}, {"lat": 41.7080, "lng": 15.9550, "label": "Monte Sant''Angelo"}, {"lat": 41.8215, "lng": 16.0090, "label": "Foresta Umbra"}, {"lat": 41.9450, "lng": 16.0140, "label": "Peschici"}, {"lat": 41.8820, "lng": 16.1760, "label": "Vieste"}, {"lat": 41.7230, "lng": 16.1180, "label": "Baia delle Zagare"}, {"lat": 41.7100, "lng": 16.0500, "label": "Mattinata"}, {"lat": 41.6260, "lng": 15.9110, "label": "Cíl: Manfredonia"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=41.6260,15.9110&destination=41.6260,15.9110&travelmode=driving&waypoints=41.7080,15.9550%7C41.8215,16.0090%7C41.9450,16.0140%7C41.8820,16.1760%7C41.7230,16.1180%7C41.7100,16.0500', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Sant%27Angelo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Peschici.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Baia%20delle%20Zagare.jpg"}'::text[], '{"Monte Sant''Angelo","Peschici","Vieste","Baia delle Zagare"}'::text[], '{"IT"}'::text[], false, 4500, 'approved');

