  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Scarperia – Palazzo dei Vicari', 'Renesanční městečko proslulé výrobou nožů a hradem Palazzo dei Vicari s erby na fasádě. Ideální start okruhu — káva na náměstí a pár kroků od historického centra k okruhu Mugello.', 43.9954, 11.3541, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palazzo%20dei%20Vicari%2C%20Scarperia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palazzo%20dei%20Vicari%2C%20Scarperia.jpg"}'::text[], 0),
    (v_route, 'Autodromo del Mugello', 'Jeden z nejkrásnějších okruhů světa, dějiště MotoGP Itálie. Z okolních kopců je výhled na trať a v areálu bývají volné jízdy — stojí za to zkontrolovat kalendář předem.', 43.9975, 11.3719, 'https://commons.wikimedia.org/wiki/Special:FilePath/Autodromo%20del%20Mugello.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Autodromo%20del%20Mugello.jpg"}'::text[], 1),
    (v_route, 'Passo del Giogo', 'Méně známý, o to prázdnější průsmyk (882 m) se sevřenými serpentinami v lese. Technická rozcvička před Futou — pozor na listí a vlhký povrch ve stínu.', 44.0480, 11.3540, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Giogo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20del%20Giogo.jpg"}'::text[], 2),
    (v_route, 'Firenzuola', 'Kamenné městečko z šedého pískovce "pietra serena", po válce znovu vystavěné. Dobrá zastávka na doplnění paliva a vody uprostřed apeninských hřebenů.', 44.1190, 11.3810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Firenzuola.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Firenzuola.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Chalet Raticosa (Passo della Raticosa)', 'Kultovní motorkářský srub přímo na vrcholu průsmyku Raticosa (968 m). O víkendu stovky motorek, výborné panini, domácí koláče a benzínkové historky — povinná zastávka každého, kdo jede SS65.', 44.1611, 11.3536, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Raticosa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Raticosa.jpg"}'::text[], 4),
    (v_route, 'Passo della Futa', 'Hlavní vrchol trasy (903 m) s výhledy na hřebeny Apenin a největším německým vojenským hřbitovem v Itálii. Plynulé, rychlé zatáčky s kvalitním asfaltem — ráj pro čistou stopu.', 44.0940, 11.2860, 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Futa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20della%20Futa.jpg"}'::text[], 5),
    (v_route, 'Lago di Bilancino', 'Přehradní jezero s plážemi na dohled od dálnice — příjemné zklidnění na závěr okruhu. V létě možnost koupání a občerstvení u vody.', 43.9800, 11.2670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Bilancino.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Bilancino.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Perugia – Fontana Maggiore', 'Hlavní město Umbrie s gotickou kašnou Fontana Maggiore a promenádou Corso Vannucci. Ranní espresso na Piazza IV Novembre je perfektní start dne.', 43.1107, 12.3908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20Maggiore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20Maggiore.jpg"}'::text[], 0),
    (v_route, 'Assisi – bazilika sv. Františka', 'Poutní město UNESCO na svahu hory Subasio. Dvoupatrová bazilika s Giottovými freskami patří k nejvýznamnějším stavbám Itálie; parkuj pod hradbami a nahoru dojdi pěšky.', 43.0748, 12.6054, 'https://commons.wikimedia.org/wiki/Special:FilePath/Assisi%20San%20Francesco%20BW%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Assisi%20San%20Francesco%20BW%202.JPG"}'::text[], 1),
    (v_route, 'Spello', 'Růžové kamenné uličky plné květináčů, římské brány a výhledy do údolí. Krátká procházka od Porta Consolare nahoru městem stojí za každý krok.', 42.9910, 12.6710, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spello.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spello.jpg"}'::text[], 2),
    (v_route, 'Montefalco', 'Vinařské městečko přezdívané "balkon Umbrie" — domov mohutného červeného Sagrantina. Z hradeb dohlédneš přes celé údolí od Perugie po Spoleto.', 42.8930, 12.6540, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montefalco.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montefalco.jpg"}'::text[], 3),
    (v_route, 'Spoleto – Ponte delle Torri', 'Středověký akvadukt vysoký 80 metrů, klenoucí se přes rokli pod pevností Rocca Albornoziana. Jedna z nejfotogeničtějších staveb Umbrie.', 42.7400, 12.7370, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spoleto%20Ponte%20delle%20Torri.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spoleto%20Ponte%20delle%20Torri.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Il Tempio del Gusto (Spoleto)', 'Vyhlášená rodinná restaurace v historickém centru Spoleta — umbrijské lanýže, čerstvá pasta strangozzi a skvělý místní vinný lístek. V sezóně rezervuj předem.', 42.7400, 12.7390, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spoleto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spoleto.jpg"}'::text[], 5),
    (v_route, 'Cascata delle Marmore', 'Umělé vodopády z dob starého Říma, celkem 165 metrů ve třech kaskádách. Voda se pouští podle harmonogramu elektrárny — zkontroluj časy, plný průtok je ohromující zážitek.', 42.5510, 12.7150, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cascata%20delle%20Marmore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cascata%20delle%20Marmore.jpg"}'::text[], 6);
  insert into public.routes
