  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ancona – katedrála San Ciriaco', 'Románská katedrála na kopci nad přístavem s výhledem na celý záliv. Od Římanů po Traianův oblouk — Ancona je starší, než vypadá z dálnice.', 43.6169, 13.5189, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Ancona.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Ancona.jpg"}'::text[], 0),
    (v_route, 'Portonovo', 'Divoká zátoka pod útesy Conera s oblázkovou pláží, pevnůstkou a románským kostelíkem u vody. Sjezd dolů je úzký a strmý — v sezóně jezdí kyvadlová doprava.', 43.5640, 13.5900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Portonovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Portonovo.jpg"}'::text[], 1),
    (v_route, 'Sirolo a pláž Due Sorelle', 'Bílé městečko na útesu s náměstíčkem-balkonem nad mořem. Pod ním ikonická pláž Due Sorelle se dvěma vápencovými věžemi — dostupná jen lodí nebo pěšky.', 43.5230, 13.6210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sirolo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sirolo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spiaggia%20delle%20Due%20Sorelle.jpg"}'::text[], 2),
    (v_route, 'Restaurace: La Torre (Numana)', 'Restaurace s terasou nad přístavem v Numaně — čerstvé jadranské ryby, moscioli (divoké slávky z Conera) a bílé Verdicchio. Jedno z nejlépe hodnocených míst riviéry.', 43.5130, 13.6220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Numana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Numana.jpg"}'::text[], 3),
    (v_route, 'Loreto – Basilica della Santa Casa', 'Jedno z nejvýznamnějších mariánských poutních míst Evropy: bazilika ukrývající Svatou chýši z Nazaretu. Opevněný chrámový komplex je vidět z celého okolí.', 43.4400, 13.6100, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Loreto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Loreto.jpg"}'::text[], 4),
    (v_route, 'Recanati', 'Rodiště básníka Giacoma Leopardiho na hřebeni mezi dvěma údolími. Vyhlídka "Colle dell''Infinito" inspirovala nejslavnější italskou báseň — a nabízí výhled až k moři.', 43.4030, 13.5490, 'https://commons.wikimedia.org/wiki/Special:FilePath/Recanati.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Recanati.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'L''Aquila – bazilika Collemaggio', 'Hlavní město Abruzza s románskou bazilikou s růžovo-bílou šachovnicovou fasádou. Město se po zemětřesení 2009 vrací k životu a centrum opět žije.', 42.3499, 13.3995, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Santa%20Maria%20di%20Collemaggio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Santa%20Maria%20di%20Collemaggio.jpg"}'::text[], 0),
    (v_route, 'Campo Imperatore', 'Šestnáct kilometrů dlouhá náhorní planina pod Corno Grande, přezdívaná "malý Tibet". Nahoře observatoř a horský hotel, kde byl vězněn Mussolini. Jedna z nejpůsobivějších silnic Itálie.', 42.4422, 13.5589, 'https://commons.wikimedia.org/wiki/Special:FilePath/Campo%20Imperatore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Campo%20Imperatore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corno%20Grande.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Ristoro Mucciante (Campo Imperatore)', 'Legendární řeznictví s grily u silnice na planině: koupíš arrosticini (ovčí špízy), sám si je opečeš na žhavém uhlí a sníš s výhledem na hory. Motorkářská klasika Abruzza.', 42.4080, 13.7150, 'https://commons.wikimedia.org/wiki/Special:FilePath/Campo%20Imperatore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Campo%20Imperatore.jpg"}'::text[], 2),
    (v_route, 'Castel del Monte', 'Kamenná pastevecká vesnice na skále v 1300 metrech, členěná do středověkých pater a průchodů. Jedna z nejzachovalejších horských vesnic Apenin.', 42.3650, 13.7260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castel%20del%20Monte%20%28AQ%29.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castel%20del%20Monte%20%28AQ%29.jpg"}'::text[], 3),
    (v_route, 'Rocca Calascio', 'Nejvýše položená hradní zřícenina Apenin (1460 m), kulisa filmů Ladyhawke i Jméno růže. Od parkoviště 20 minut pěšky; západ slunce odsud je nezapomenutelný.', 42.3280, 13.6880, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rocca%20Calascio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rocca%20Calascio.jpg"}'::text[], 4),
    (v_route, 'Santo Stefano di Sessanio', 'Dokonale zachovaná středověká vesnice z medově zbarveného kamene, citlivě oživená jako "rozptýlený hotel". Úzké uličky, klenuté průchody a ticho hor.', 42.3430, 13.6460, 'https://commons.wikimedia.org/wiki/Special:FilePath/Santo%20Stefano%20di%20Sessanio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Santo%20Stefano%20di%20Sessanio.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Alba', 'Hlavní město Langhe, metropole bílých lanýžů a čokolády (rodiště Nutelly). Středověké věže, sobotní trh a na podzim slavný lanýžový veletrh.', 44.7009, 8.0353, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Alba.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Alba.jpg"}'::text[], 0),
    (v_route, 'Castello di Grinzane Cavour', 'Pohádkový hrad hraběte Cavoura uprostřed vinic, dnes UNESCO, muzeum vína a dějiště světové aukce lanýžů. Nejfotografovanější silueta Langhe.', 44.6560, 8.0090, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Grinzane%20Cavour.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Grinzane%20Cavour.jpg"}'::text[], 1),
    (v_route, 'La Morra – vyhlídka Belvedere', 'Vesnice na nejvyšším kopci oblasti s vyhlídkovou terasou nad mořem vinic — za jasného dne vidíš Monviso i Monte Rosu. Srdce apelace Barolo.', 44.6370, 7.9330, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%20Morra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Morra.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Ristorante Bovio (La Morra)', 'Rodinná restaurace s panoramatickou terasou nad vinicemi — piemontská klasika: tajarin s lanýžem, vitello tonnato, carne cruda. Jedno z nejoblíbenějších míst Langhe, rezervuj.', 44.6360, 7.9350, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%20Morra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Morra.jpg"}'::text[], 3),
    (v_route, 'Barolo – Castello Falletti', 'Vesnička, která dala jméno "králi vín". Na hradě Falletti sídlí interaktivní muzeum vína WiMu a v podhradí desítky enoték na ochutnávku (pro spolujezdce).', 44.6110, 7.9430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Barolo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Barolo.jpg"}'::text[], 4),
    (v_route, 'Serralunga d''Alba', 'Nejštíhlejší hrad Piemontu — gotická věžová pevnost ze 14. století trčící nad vesnicí jako maják vinic. Krásný okruh uličkami kolem hradního návrší.', 44.6100, 8.0000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Serralunga%20d%27Alba.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Serralunga%20d%27Alba.jpg"}'::text[], 5),
    (v_route, 'Barbaresco', 'Druhá velká apelace nebbiola s charakteristickou středověkou věží nad řekou Tanaro. Z vrcholu věže panoráma celých Langhe — důstojná tečka okruhu.', 44.7260, 8.0810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barbaresco.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Barbaresco.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Forte di Bard', 'Mohutná napoleonská pevnost přehrazující celé údolí — dnes muzeum Alp a kulisa z filmu Avengers 2. Nahoru vedou prosklené šikmé výtahy, výhled je velkolepý.', 45.6080, 7.7440, 'https://commons.wikimedia.org/wiki/Special:FilePath/Forte%20di%20Bard.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Forte%20di%20Bard.jpg"}'::text[], 0),
    (v_route, 'Castello di Fénis', 'Nejslavnější hrad údolí: dokonalá středověká pevnost s dvojitými hradbami, věžičkami a freskami na nádvoří. Vypadá přesně tak, jak si hrad představuje každé dítě.', 45.7360, 7.4900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20F%C3%A9nis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20F%C3%A9nis.jpg"}'::text[], 1),
    (v_route, 'Aosta – Arco di Augusto', 'Řím v Alpách: triumfální oblouk, městské brány a divadlo z dob císaře Augusta. Kompaktní centrum projdeš za hodinu, kavárny na Piazza Chanoux svádějí k delší pauze.', 45.7390, 7.3260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arco%20di%20Augusto%20Aosta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arco%20di%20Augusto%20Aosta.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Osteria da Nando (Aosta)', 'Rodinná osteria v centru Aosty fungující od roku 1957 — fondue, polenta s dušeným masem a valdostánská vína. Poctivá horská kuchyně za férové ceny.', 45.7370, 7.3200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arco%20di%20Augusto%20Aosta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arco%20di%20Augusto%20Aosta.jpg"}'::text[], 3),
    (v_route, 'Castello di Saint-Pierre', 'Nejfotogeničtější hrad regionu — pohádková silueta se čtyřmi věžičkami na skále přímo nad silnicí SS26. Uvnitř přírodovědné muzeum, zvenku povinná fotka.', 45.7100, 7.2230, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Saint-Pierre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castello%20di%20Saint-Pierre.jpg"}'::text[], 4),
    (v_route, 'Courmayeur', 'Elegantní horské středisko na úpatí Mont Blanku, konec italské strany masivu. Pěší zóna s horskými butiky a výhledy na ledovce Brenvy.', 45.7920, 6.9720, 'https://commons.wikimedia.org/wiki/Special:FilePath/Courmayeur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Courmayeur.jpg"}'::text[], 5),
    (v_route, 'Skyway Monte Bianco', 'Futuristická lanovka s otočnými kabinami na Punta Helbronner (3466 m) — terasa s výhledem na Mont Blanc, Matterhorn i Gran Paradiso. Motorku nech na hlídaném parkovišti u dolní stanice.', 45.8140, 6.9660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skyway%20Monte%20Bianco.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skyway%20Monte%20Bianco.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Bianco.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Dolceacqua', 'Vesnice s hrbatým středověkým mostem a hradem Doria, kterou Claude Monet označil za "klenot lehkosti". Ochutnej místní červené Rossese — a pozor, most je jen pro pěší.', 43.8480, 7.6220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dolceacqua.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dolceacqua.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Ristorante Apricale da Delio (Apricale)', 'Rodinný podnik na náměstíčku v Apricale — králík po ligursku, domácí ravioli a olivový olej z vlastního háje. Jedna z nejlepších tradičních kuchyní vnitrozemí.', 43.8800, 7.6600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Apricale.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Apricale.jpg"}'::text[], 1),
    (v_route, 'Apricale', 'Orlí hnízdo z kamene rozlévající se po hřebeni — jedna z oficiálně nejkrásnějších vesnic Itálie. Auta zůstávají venku, uličkami se jen chodí.', 43.8800, 7.6600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Apricale.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Apricale.jpg"}'::text[], 2),
    (v_route, 'Pigna', 'Terasovitá vesnice nad údolím Nervia se středověkým jádrem a termálními prameny. Odsud začíná nejdivočejší úsek trasy přes sedlo do údolí Argentina.', 43.9320, 7.6620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pigna%20%28Imperia%29.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pigna%20%28Imperia%29.jpg"}'::text[], 3),
    (v_route, 'Triora', '"Vesnice čarodějnic" — dějiště největšího čarodějnického procesu Itálie (1587). Tajemné kamenné uličky, muzeum čarodějnictví a výhledy na hřebeny Ligurských Alp.', 44.0000, 7.7640, 'https://commons.wikimedia.org/wiki/Special:FilePath/Triora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Triora.jpg"}'::text[], 4),
    (v_route, 'Taggia', 'Městečko oliv taggiasca s monumentálním středověkým mostem o šestnácti obloucích. Tady se rodí nejslavnější italský olivový olej — kup lahev do kufru.', 43.8620, 7.8510, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taggia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Taggia.jpg"}'::text[], 5),
    (v_route, 'Sanremo', 'Město květin, kasina a slavného hudebního festivalu. Projeď po pobřežní promenádě Imperatrice a dej si kávu v přístavu — návrat do civilizace po horských samotách.', 43.8160, 7.7760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanremo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sanremo.jpg"}'::text[], 6);
