    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Syrakusy – Ortigia', 'Ostrovní stará čtvrť Syrakus: katedrála vestavěná do antického Athénina chrámu, barokní náměstí a pramen Aretusa u moře. Kdysi největší město antického světa.', 37.0590, 15.2930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Siracusa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Siracusa.jpg"}'::text[], 0),
    (v_route, 'Noto – katedrála', 'Hlavní město sicilského baroka — celé postavené z medového vápence, který při západu slunce hoří zlatem. Monumentální schodiště katedrály a korzo Vittorio Emanuele jsou povinnost.', 36.8910, 15.0690, 'https://commons.wikimedia.org/wiki/Special:FilePath/Noto%20Cathedral.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Noto%20Cathedral.jpg"}'::text[], 1),
    (v_route, 'Marzamemi', 'Bývalá tuňáková osada s náměstíčkem přímo u vody — dnes nejfotogeničtější rybářská vesnice Sicílie. Ochutnej bottargu nebo granitu u přístavu.', 36.7370, 15.1180, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marzamemi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Marzamemi.jpg"}'::text[], 2),
    (v_route, 'Scicli', 'Barokní městečko sevřené v kaňonu, známé jako "Vigàta" ze seriálu Komisař Montalbano. Via Mormino Penna patří k nejhezčím barokním ulicím Itálie.', 36.7900, 14.7060, 'https://commons.wikimedia.org/wiki/Special:FilePath/Scicli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Scicli.jpg"}'::text[], 3),
    (v_route, 'Modica', 'Město čokolády vyráběné za studena podle aztécké receptury a barokního chrámu San Giorgio na 250 schodech. Domy tu šplhají po stěnách kaňonu jedno nad druhým.', 36.8590, 14.7610, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modica.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Antica Dolceria Bonajuto (Modica)', 'Nejstarší čokoládovna Sicílie (1880) v uličce pod chrámem San Giorgio — křupavá modická čokoláda s vanilkou či chilli a legendární "mpanatigghi" s masem a kakaem. Sladká povinná zastávka.', 36.8580, 14.7600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modica.jpg"}'::text[], 5),
    (v_route, 'Ragusa Ibla', 'Barokní stará čtvrť na skalním ostrohu — labyrint schodišť a paláců korunovaný kupolí chrámu San Giorgio. Nejkrásnější pohled je z vyhlídky u kostela Santa Maria delle Scale.', 36.9210, 14.7400, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ragusa%20Ibla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ragusa%20Ibla.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Arbatax – Rocce Rosse', 'Červené porfyrové skály trčící přímo z moře u přístavu Arbatax — ikonický start východosardinské cesty. Ráno tu bývá klid a nejlepší světlo na fotku.', 39.9410, 9.7070, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arbatax.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arbatax.jpg"}'::text[], 0),
    (v_route, 'Baunei', 'Horská vesnice přilepená na svahu 500 metrů nad mořem, brána k zázračným plážím zálivu Orosei. Z terasy u kostela přehlédneš celé pobřeží.', 40.0310, 9.6660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baunei.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baunei.jpg"}'::text[], 1),
    (v_route, 'Gola di Gorropu', 'Nejhlubší kaňon Evropy — vápencové stěny až 500 metrů vysoké. Od sedla Genna Silana na SS125 vede k okraji soutěsky stezka; i samotná vyhlídka od silnice bere dech.', 40.1450, 9.4890, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gola%20di%20Gorropu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gola%20di%20Gorropu.jpg"}'::text[], 2),
    (v_route, 'Dorgali', 'Živé městečko pod masivem Supramonte, centrum řemesel — kůže, keramika, filigrán a víno Cannonau. Dobrá zastávka na kávu a doplnění zásob.', 40.2910, 9.5900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dorgali.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dorgali.jpg"}'::text[], 3),
    (v_route, 'Cala Gonone', 'Přímořské letovisko v amfiteátru hor, výchozí bod k plážím Cala Luna a jeskyni Bue Marino. Sjezd z tunelu nad městem patří k nejhezčím kilometrům trasy.', 40.2820, 9.6350, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala%20Gonone.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cala%20Gonone.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Il Pescatore (Cala Gonone)', 'Rybí restaurace u přístavu v Cala Gonone — čerstvý úlovek dne, špagety s mořskými plody a sardinské Vermentino s výhledem na záliv Orosei.', 40.2830, 9.6360, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala%20Gonone.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cala%20Gonone.jpg"}'::text[], 5),
    (v_route, 'Orgosolo – murály', 'Pastevecká vesnice v srdci Barbagie proslulá stovkami politických murálů na fasádách domů. Syrová, opravdová Sardinie daleko od plážových letovisek.', 40.2050, 9.3540, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orgosolo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orgosolo.jpg"}'::text[], 6);
