  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Monte Sant''Angelo', 'Poutní město v 800 metrech s jeskynní svatyní archanděla Michaela (UNESCO), kam mířili poutníci už od 5. století. Z hradeb výhled přes celý Manfredonský záliv.', 41.7080, 15.9550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Sant%27Angelo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Sant%27Angelo.jpg"}'::text[], 0),
    (v_route, 'Foresta Umbra', 'Prastarý bukový prales v srdci Gargana, zapsaný na seznamu UNESCO. Stinné serpentiny rezervací jsou v letním vedru balzám — u návštěvnického centra jezírko s daňky.', 41.8215, 16.0090, 'https://commons.wikimedia.org/wiki/Special:FilePath/Foresta%20Umbra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Foresta%20Umbra.jpg"}'::text[], 1),
    (v_route, 'Peschici', 'Bílé městečko na útesu nad vlastní zátokou s plážemi. Labyrint arabsky působících uliček a výhledy na dřevěné rybářské konstrukce trabucchi pod útesy.', 41.9450, 16.0140, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peschici.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peschici.jpg"}'::text[], 2),
    (v_route, 'Vieste', 'Hlavní město Gargana s monolitem Pizzomunno u pláže — 25 metrů vysokou vápencovou věží opředenou legendou. Stará čtvrť na skále nad mořem je stvořená k večerní procházce.', 41.8820, 16.1760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Osteria al Duomo (Vieste)', 'Osteria v kamenném sklepení ve staré čtvrti Vieste — orecchiette s mořskými plody, grilované ryby a apulské Primitivo. Výborně hodnocená klasika u katedrály.', 41.8830, 16.1770, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vieste.jpg"}'::text[], 4),
    (v_route, 'Baia delle Zagare', 'Nejfotografovanější zátoka Jadranu: dva vápencové skalní oblouky vystupující z tyrkysové vody pod bílými útesy. Vyhlídka přímo u silnice SS89.', 41.7230, 16.1180, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baia%20delle%20Zagare.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baia%20delle%20Zagare.jpg"}'::text[], 5),
    (v_route, 'Mattinata', '"Bílý motýl" Gargana — městečko rozložené na dvou kopcích mezi olivovými háji nad mořem. Poslední kávová zastávka před návratem do Manfredonie.', 41.7100, 16.0500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mattinata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mattinata.jpg"}'::text[], 6);
